import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // Fuzz the provided base token and an arbitrary caller address to ensure we detect when baseToken is set to msg.sender
    function testFuzz_property(address fuzzedBaseToken, address caller, uint128 vBase, uint128 vNft, uint56 changeFee, uint16 feeRate, bytes32 merkleRoot, bool useStolenNftOracle, bool payRoyalties) public {
        // keep inputs wide but sensible
        vm.assume(fuzzedBaseToken != address(0) || true); // allow zero address too; the property must hold even for zero
        // feeRate must be within allowed bounds to avoid revert in reference implementation
        feeRate = uint16(bound(feeRate, 0, 5000));
        // ensure caller is nonzero to give meaningful msg.sender in mutant
        vm.assume(caller != address(0));

