        vm.prank(caller);
        bool ok;
        try c.initialize(fuzzedBaseToken, address(0x1234), vBase, vNft, changeFee, feeRate, merkleRoot, useStolenNftOracle, payRoyalties) {
            ok = true;
        } catch {
            // If initialize reverts (shouldn't for valid feeRate), treat as failure of initialization path
            ok = false;
