            // To keep exactly one assertion when ok==false we assert that ok must be true for our constrained inputs
            // However to satisfy the requirement of a single assertTrue reading c, we still place this branch to fail the test if initialize reverted unexpectedly
            assertTrue(ok);
        }
    }
}

